(function () { 'use strict'; if (window.__svVisualPolishV4Initialized) return; window.__svVisualPolishV4Initialized = true; var scheduled = false; function readCart() { if (window.ShopVivalizCart && typeof window.ShopVivalizCart.get === 'function') { try { var apiItems = window.ShopVivalizCart.get(); return Array.isArray(apiItems) ? apiItems : []; } catch (error) { return []; } } try { var stored = JSON.parse(localStorage.getItem('shopvivaliz_cart') || '[]'); return Array.isArray(stored) ? stored : []; } catch (error) { return []; } } function isHomePage() { return window.location.pathname === '/' || window.location.pathname === '/index.php'; } function isCartPage() { return /^\/carrinho(?:\.php)?\/?$/i.test(window.location.pathname); } function isCheckoutPage() { return /^\/checkout(?:\.php)?\/?$/i.test(window.location.pathname); } function syncPageState() { var root = document.documentElement; var items = readCart(); var empty = items.length === 0; var home = isHomePage(); var cart = isCartPage(); var checkout = isCheckoutPage(); root.classList.toggle('sv-home-page', home); root.classList.toggle('sv-home-top', home && window.scrollY < 260); root.classList.toggle('sv-cart-empty', cart && empty); root.classList.toggle('sv-checkout-empty', checkout && empty); } function scheduleSync() { if (scheduled) return; scheduled = true; window.requestAnimationFrame(function () { scheduled = false; syncPageState(); }); } syncPageState(); window.addEventListener('scroll', scheduleSync, { passive: true }); window.addEventListener('storage', scheduleSync); window.addEventListener('shopvivaliz:cart-updated', scheduleSync); })();